sol:
cat <<EOF | k apply -f -
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: deny-all, namespace: backend}
spec: {podSelector: {}, policyTypes: [Ingress]}
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata: {name: web-to-api, namespace: backend}
spec:
  podSelector: {matchLabels: {app: api}}
  policyTypes: [Ingress]
  ingress:
  - from:
    - namespaceSelector: {matchLabels: {kubernetes.io/metadata.name: frontend}}
      podSelector: {matchLabels: {app: web}}
    ports: [{protocol: TCP, port: 8080}]
EOF

startupProbe:
  httpGet: {path: /healthz, port: 8080}
  periodSeconds: 2
  failureThreshold: 30
readinessProbe:
  httpGet: {path: /ready, port: 8080}
livenessProbe:
  httpGet: {path: /healthz, port: 8080}
  periodSeconds: 10

apiVersion: v1
kind: PersistentVolume
metadata: {name: pv-log}
spec: {capacity: {storage: 1Gi}, accessModes: [ReadWriteOnce], persistentVolumeReclaimPolicy: Retain, storageClassName: manual, hostPath: {path: /mnt/log}}
---
apiVersion: v1
kind: PersistentVolumeClaim
metadata: {name: log-claim}
spec: {accessModes: [ReadWriteOnce], storageClassName: manual, resources: {requests: {storage: 1Gi}}}
---
k get pv pv-log    # Bound

volumes:
- name: shared
  emptyDir: {medium: Memory, sizeLimit: 64Mi}
containers:
- {name: writer, image: busybox:1.36, command: ['sh','-c','while true; do date >> /shared/t; sleep 5; done'], volumeMounts: [{name: shared, mountPath: /shared}]}
- {name: reader, image: busybox:1.36, command: ['sh','-c','tail -F /shared/t'], volumeMounts: [{name: shared, mountPath: /shared}]}
